// F4: plain `qa start` over an already-completed current attempt republishes
// map shards (mapped phase, no theories) over terminal shard records.
func TestReproFreshStartOverwritesCompletedShardEvidence(t *testing.T) {
	root, sp, publication := qaPublicationFixture(t)
	token := QAWriterToken{RunID: "run-1", OperationalAttemptID: "op-1", FencingGeneration: 1}
	store := NewQAStore(root, sp).WithWriterFence(func(QAWriterToken) error { return nil })
	if err := store.Publish(publication, token); err != nil {
		t.Fatal(err)
	}
	completed := publication.Shards[0]
	completed.Phase = QAPhaseCompleted
	theoryID, _ := NewQATheoryID(sp.Project, sp.Slug, completed.ID, QATheoryIdentity{Claim: "c", Basis: "b", VerificationSurface: "internal/a.go", ExpectationRefs: []string{"REQ-1"}})
	completed.Theories = []QATheory{{SchemaVersion: 1, ID: theoryID, ShardID: completed.ID, Claim: "c", Basis: "b", VerificationSurface: "internal/a.go", ExpectationRefs: []string{"REQ-1"}, SeverityIfConfirmed: "medium", ConfirmationCondition: "c", RefutationCondition: "r", InconclusiveCondition: "i", SafeEvidenceStrategy: "s", ImplementationFingerprint: testQAFingerprint, AttemptHistory: []QAInvestigatorAttempt{{ID: "x", Number: 1, StartedAt: time.Unix(1, 0)}}, Outcome: QATheoryRefuted, OutcomeReason: "observed"}}
	if err := store.Publish(QAPublication{Shards: []QAShard{completed}}, token); err != nil {
		t.Fatal(err)
	}
	// A fresh start re-runs prepareQAAttempt without Resume; the map shard
	// replaces the retained terminal record in the same attempt directory.
	service := NewService(root).WithQASettings(QASettings{Runtime: StageRuntime{Model: "openai/qa"}, Budgets: publication.Map.Budgets})
	flow, err := LoadFlowState(root, sp)
	if err != nil {
		t.Fatal(err)
	}
	if _, shards, err := service.prepareQAAttempt(store, flow, *publication.Map, QARunRequest{WriterToken: token}, QASettings{Runtime: StageRuntime{Model: "openai/qa"}, Budgets: publication.Map.Budgets}); err != nil {
		t.Fatal(err)
	} else if shards[0].Phase != QAPhaseMapped || len(shards[0].Theories) != 0 {
		t.Fatalf("expected map shard to replace terminal record: %+v", shards[0])
	}
	reloaded, err := store.LoadShard(publication.Map.SemanticAttemptID, completed.ID)
	if err != nil {
		t.Fatal(err)
	}
	if len(reloaded.Theories) != 0 || reloaded.Phase == QAPhaseCompleted {
		t.Fatalf("retained investigator evidence was destroyed by a fresh start: %+v", reloaded)
	}
}
EOF
go test ./internal/sprint/ -run 'TestRepro' -count=1 2>&1 | tail -4

