func TestReproFormatCheckDetectionBlocksRequestingShard(t *testing.T) {
	target := t.TempDir()
	if err := os.MkdirAll(filepath.Join(target, "internal"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(target, "internal", "a.go"), []byte("package internal\nfunc f() {\nx := 1\n_ = x\n}\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	budgets := DefaultQABudgets()
	checks, err := ApprovedQAChecks(target, []string{"internal/a.go"}, budgets)
	if err != nil {
		t.Fatal(err)
	}
	input := qaMapInputFixture()
	input.ChangedPaths = []string{"internal/a.go"}
	identity, err := targetIdentity(target)
	if err != nil {
		t.Fatal(err)
	}
	input.ImplementationFingerprint = identity
	input.Target.Fingerprint = identity
	input.ApprovedChecks = []QAApprovedCheckRef{{ID: checks[0].ID, Fingerprint: checks[0].Fingerprint}}
	input.Settings.Budgets = budgets
	qaMap, err := BuildQAMap(input)
	if err != nil {
		t.Fatal(err)
	}
	service := NewService(t.TempDir()).WithRuntime(qaCheckRequestingRuntime{checks: qaMap.Shards[0].ApprovedChecks}).WithQASettings(QASettings{Runtime: StageRuntime{Model: "openai/qa"}, Budgets: budgets}).WithQAMapFence(func(QAMap) error { return nil })
	shard, err := service.runOneQAShard(context.Background(), qaMap, qaMap.Shards[0], target, QAWriterToken{RunID: "r", OperationalAttemptID: "o", FencingGeneration: 1})
	if err == nil {
		t.Fatal("expected the format-drift detection to be treated as a shard failure")
	}
	if typed, ok := AsQAError(err); !ok || typed.Category != QAErrorRuntimeUnavailable {
		t.Fatalf("error = %v", err)
	}
	if len(shard.Theories) != 0 {
		t.Fatalf("theories should have been discarded: %+v", shard.Theories)
	}
	t.Logf("blocked shard blocker=%+v attempts=%d", shard.Blocker, len(shard.Attempts))
}
EOF
